import { useJobNotificationsSocketIo } from "@/hooks/socketio/useJobNotificationsSocketIo"
import { PublicationEvent } from "@/hooks/socketio/enums/publication-event"
import { JobCategory } from "@/modules/types/enums/job-category"
import { JobStatus } from "@/modules/types/enums/job-status"
import { useAppSelector } from "@/redux/hooks"
import { StackH, StackV } from "@/components/frames/Stack"
import { Cluster } from "@/components/frames/Cluster"
import { Box } from "@/components/frames/Box"

/** Props for {@link PracticeProblemPage}. */
export type PracticeProblemPageProps = Record<string, never>

/** Seniority level i18n key per difficulty (easy=junior, medium=mid, hard=senior). */
const LEVEL_KEY: Record<CodingDifficulty, string> = {
    [CodingDifficulty.Easy]: "junior",
    [CodingDifficulty.Medium]: "mid",
    [CodingDifficulty.Hard]: "senior",
}

/** Difficulty → chip tone (mirrors the list-card difficulty palette). */
const DIFFICULTY_TONE: Record<CodingDifficulty, StatusChipTone> = {
    [CodingDifficulty.Easy]: "success",
    [CodingDifficulty.Medium]: "warning",
    [CodingDifficulty.Hard]: "danger",
}

/** Map a coding language to its Monaco editor language id. */
const MONACO_LANGUAGE: Record<CodingLanguage, string> = {
    [CodingLanguage.Python]: "python",
    [CodingLanguage.JavaScript]: "javascript",
    [CodingLanguage.TypeScript]: "typescript",
    [CodingLanguage.Java]: "java",
    [CodingLanguage.Cpp]: "cpp",
}

/** Chip tone per verdict (accepted = success, terminal failures = danger). */
const VERDICT_TONE: Record<CodingVerdict, StatusChipTone> = {
    [CodingVerdict.Accepted]: "success",
    [CodingVerdict.WrongAnswer]: "danger",
    [CodingVerdict.TimeLimitExceeded]: "danger",
    [CodingVerdict.MemoryLimitExceeded]: "danger",
    [CodingVerdict.RuntimeError]: "danger",
    [CodingVerdict.CompileError]: "danger",
    [CodingVerdict.InternalError]: "warning",
    [CodingVerdict.Pending]: "neutral",
    [CodingVerdict.Judging]: "neutral",
}

/** Left-pane tab ids. */
type LeftTab = "description" | "solution" | "submissions"
/** Console (right-pane bottom) tab ids. */
type ConsoleTab = "testcase" | "result"

/** Terminal job statuses — judging has finished (success or failure). */
const isTerminalStatus = (status: JobStatus | undefined): boolean =>
    status === JobStatus.Completed || status === JobStatus.Failed

/**
 * Coding-problem detail + editor — a full-bleed 2-pane IDE (`/practice/[slug]`).
 * LEFT = tabbed reading column (`ExtendedTabs`: Description / Solution / Submissions);
 * RIGHT = Monaco editor over a `CodeConsole` (Test case / Result) whose result
 * tab renders the judged PER-CASE outcome (`TestCaseResultGrid` off the API's
 * `perCaseResults`) plus runtime/memory stats. The submit → async-judge →
 * realtime-verdict flow (SWR + `/job_notifications` socket + anti-cheat
 * telemetry) is unchanged from the prior build; only the shell is new.
 */
export const PracticeProblemPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const params = useParams()
    const slug = String(params.slug ?? "")
    const { theme } = useTheme()
    const socket = useJobNotificationsSocketIo()

    const [language, setLanguage] = useState<CodingLanguage>(CodingLanguage.Python)
    const [code, setCode] = useState<string>("")
    const [pendingJobId, setPendingJobId] = useState<string | null>(null)
    const [submitting, setSubmitting] = useState(false)
    const [leftTab, setLeftTab] = useState<LeftTab>("description")
    const [consoleTab, setConsoleTab] = useState<ConsoleTab>("testcase")
    // Live job status mirrored from Redux — the global /job_notifications lifecycle
    // dispatches every subscribed job's status into socketIo.jobStatusByJobId, the same
    // single source the challenge panel reads (no per-component EventEmitter listener).
    const pendingJobMessage = useAppSelector((state) =>
        (pendingJobId ? state.socketIo.jobStatusByJobId[pendingJobId] : undefined))
    const pendingJobStatus = pendingJobMessage?.data?.status
    const pendingJobError = pendingJobMessage?.data?.error
    const [showHint, setShowHint] = useState(false)
    const [showSolution, setShowSolution] = useState(false)
    // reference solutions arrive ONLY from the gated reveal mutation (never the
    // problem detail read) — held here once the learner reveals them
    const [revealedSolutions, setRevealedSolutions] = useState<Array<CodingProblemSolution>>([])
    const [solutionLanguage, setSolutionLanguage] = useState<CodingLanguage>(CodingLanguage.Python)
    const [touchedLanguages, setTouchedLanguages] = useState<Set<CodingLanguage>>(new Set())

    const telemetryRef = useRef({
        pasteCount: 0,
        pasteSizeMax: 0,
        keystrokeCount: 0,
        tabBlurCount: 0,
        timeOpen: Date.now(),
    })

    // Reset telemetry when the slug changes (user selects a new problem)
    useEffect(() => {
        telemetryRef.current = {
            pasteCount: 0,
            pasteSizeMax: 0,
            keystrokeCount: 0,
            tabBlurCount: 0,
            timeOpen: Date.now(),
        }
    }, [slug])

    // Track when window loses focus (user switching browser tabs/windows)
    useEffect(() => {
        const handleBlur = () => {
            telemetryRef.current.tabBlurCount += 1
        }
        window.addEventListener("blur", handleBlur)
        return () => window.removeEventListener("blur", handleBlur)
    }, [])

    const {
        data: problem,
        isLoading,
        error: problemError,
        mutate: mutateProblem,
    } = useSWR<CodingProblem | null>(
        ["coding-problem", slug],
        async () => {
            const response = await queryCodingProblem({ request: { slug } })
            return response.data?.codingProblem.data ?? null
        },
    )

    const { data: hint } = useSWR<string | null>(
        ["coding-problem-hint", slug],
        async () => {
            const response = await queryCodingProblemHint({ request: { slug } })
            return response.data?.codingProblemHint.data?.hint ?? null
        },
    )

    const { data: submissionsData, mutate: mutateSubmissions } = useSWR(
        ["my-coding-submissions", slug],
        async () => {
            const response = await queryMyCodingSubmissions({
                request: { slug, page: 1, limit: 20 },
            })
            return response.data?.myCodingSubmissions.data ?? null
        },
    )

    const starterByLanguage = useMemo(() => {
        const map = new Map<CodingLanguage, string>()
        problem?.starterCodes?.forEach((starter) => map.set(starter.language, starter.code))
        return map
    }, [problem?.starterCodes])

    const languages = useMemo<Array<CodingLanguage>>(() => {
        const withStarter = problem?.starterCodes?.map((starter) => starter.language) ?? []
        return withStarter.length > 0 ? withStarter : Object.values(CodingLanguage)
    }, [problem?.starterCodes])

    useEffect(() => {
        if (languages.length > 0 && !languages.includes(language)) {
            setLanguage(languages[0])
        }
    }, [languages, language])

    useEffect(() => {
        if (!touchedLanguages.has(language)) {
            setCode(starterByLanguage.get(language) ?? "")
        }
    }, [language, starterByLanguage, touchedLanguages])

    const latestSubmission = useMemo<CodingSubmission | undefined>(
        () => submissionsData?.submissions[0],
        [submissionsData?.submissions],
    )

    // decode the judged per-case outcome (input/expected/got for samples) — the
    // data the API always returned but the old UI threw away.
    const resultCases = useMemo<Array<TestCaseResult>>(
        () => parsePerCaseResults(latestSubmission?.perCaseResults ?? null).map((perCase) => ({
            key: String(perCase.orderIndex),
            label: t("codingPractice.caseLabel", { index: perCase.orderIndex }),
            passed: perCase.verdict === CodingVerdict.Accepted,
            isSample: perCase.isSample,
            input: perCase.input,
            expectedOutput: perCase.expectedOutput,
            got: perCase.stdout,
        })),
        [latestSubmission?.perCaseResults, t],
    )

    // reference solution code keyed by language (revealed in the "answer" panel)
    const solutionByLanguage = useMemo(() => {
        const map = new Map<CodingLanguage, string>()
        revealedSolutions.forEach((solution) => map.set(solution.language, solution.code))
        return map
    }, [revealedSolutions])

    // languages that actually ship a reference solution
    const solutionLanguages = useMemo<Array<CodingLanguage>>(
        () => revealedSolutions.map((solution) => solution.language),
        [revealedSolutions],
    )

    // keep the solution language switcher pinned to an available language
    useEffect(() => {
        if (solutionLanguages.length > 0 && !solutionLanguages.includes(solutionLanguage)) {
            setSolutionLanguage(solutionLanguages[0])
        }
    }, [solutionLanguages, solutionLanguage])

    /** Back to the practice catalog. */
    const onBack = useCallback(
        () => router.push(pathConfig().locale(locale).practice().build()),
        [router, locale],
    )

    /** Reset the editor to the language's starter code (drops local edits). */
    const onResetCode = useCallback(() => {
        setCode(starterByLanguage.get(language) ?? "")
        setTouchedLanguages((prev) => {
            const next = new Set(prev)
            next.delete(language)
            return next
        })
    }, [language, starterByLanguage])

    // toggle the answer panel; revealing it forfeits the problem's points, so
    // confirm first and record the reveal server-side (best-effort)
    const onToggleSolution = useCallback(async () => {
        if (showSolution) {
            setShowSolution(false)
            return
        }
        if (!window.confirm(t("codingPractice.revealConfirm"))) {
            return
        }
        try {
            // the gated reveal mutation both records the forfeit AND returns the
            // reference solutions — the only path by which they reach the client
            const response = await mutateRevealCodingSolution({ request: { slug } })
            setRevealedSolutions(response.data?.revealCodingSolution.data?.solutions ?? [])
            setShowSolution(true)
        } catch {
            // reveal failed (network/auth) — keep the answer panel closed
        }
    }, [showSolution, slug, t])

    const onSubmit = useCallback(async () => {
        setSubmitting(true)
        setConsoleTab("result")
        try {
            const timeOpenToSubmitMs = Date.now() - telemetryRef.current.timeOpen
            const response = await mutateSubmitCodingSolution({
                request: {
                    slug,
                    language,
                    sourceCode: code,
                    telemetry: {
                        pasteCount: telemetryRef.current.pasteCount,
                        pasteSizeMax: telemetryRef.current.pasteSizeMax,
                        keystrokeCount: telemetryRef.current.keystrokeCount,
                        tabBlurCount: telemetryRef.current.tabBlurCount,
                        timeOpenToSubmitMs,
                    },
                },
            })
            const jobId = response.data?.submitCodingSolution.data?.jobId
            if (!jobId) return
            // Subscribe to the job room BEFORE the refetch so an early socket push is
            // never missed (race-free, like challenge). Status comes from Redux.
            setPendingJobId(jobId)
            socket.emit(PublicationEvent.SubscribeJobNotification, {
                data: { jobId },
                locale,
            })
            void mutateSubmissions()
        } finally {
            setSubmitting(false)
        }
    }, [slug, language, code, mutateSubmissions, socket, locale])

    // When the watched job reaches a terminal status (from Redux), refetch the
    // submissions (verdict now persisted) and stop watching.
    useEffect(() => {
        if (pendingJobId && isTerminalStatus(pendingJobStatus)) {
            void mutateSubmissions()
            setPendingJobId(null)
        }
    }, [pendingJobId, pendingJobStatus, mutateSubmissions])

    const judging = pendingJobId !== null

    // first load in flight → skeleton
    if (isLoading) {
        return <PracticeProblemSkeleton />
    }

    // load resolved with no problem: either a network/GraphQL error (`problemError`)
    // or the BE's uniform 404 for an unknown/disabled slug (fetcher yields `null`).
    // Distinguish the two, and never leave the skeleton spinning forever.
    if (!problem) {
        return (
            <div className="flex h-[calc(100vh-4rem)] flex-col">
                <Box principle="page-pad" className="flex flex-col border-b border-default px-6 py-3"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    <BackLink target={t("codingPractice.title")} onPress={onBack} />
                </Box>
                <Box principle="page-pad" className="flex min-h-0 flex-1 items-center justify-center px-6"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    {problemError ? (
                        <AsyncContentError
                            title={t("codingPractice.detailError")}
                            description={t("codingPractice.detailErrorHint")}
                            onRetry={() => { void mutateProblem() }}
                            retryLabel={t("common.retry")}
                        />
                    ) : (
                        <EmptyState
                            icon={MagnifyingGlassIcon}
                            title={t("codingPractice.notFound")}
                            description={t("codingPractice.notFoundHint")}
                            action={() => (
                                <Button variant="primary" size="sm" onPress={onBack}>
                                    {t("codingPractice.backToPractice")}
                                </Button>
                            )}
                        />
                    )}
                </Box>
            </div>
        )
    }

    const samples = problem.testcases ?? []
    const memoryMb = problem.memoryLimitKb ? Math.round(problem.memoryLimitKb / 1024) : null

    /** LEFT: problem statement, samples, hint. */
    const descriptionPanel = (
        <StackV gap={6} principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            items={[
                () => (
                    <StackV gap={4} principle="card-caption"
                        explain="Holds caption text under card media so the caption stays attached to the image above it."
                        items={[
                            () => (
                                <StackH gap={3} principle="flex-action"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    items={[
                                        () => <Typography type="h4" weight="bold">{problem.title}</Typography>,
                                        () => (
                                            <StatusChip tone={DIFFICULTY_TONE[problem.difficulty]}>
                                                {t(`codingPractice.level.${LEVEL_KEY[problem.difficulty]}`)}
                                            </StatusChip>
                                        ),
                                    ]} />
                            ),
                            () => (
                                <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted">
                                    <span>{t("codingPractice.points", { points: problem.points })}</span>
                                    {problem.timeLimitMs ? <span>· {t("codingPractice.timeLimit", { ms: problem.timeLimitMs })}</span> : null}
                                    {memoryMb ? <span>· {t("codingPractice.memoryLimit", { mb: memoryMb })}</span> : null}
                                    {problem.tags.map((tag) => <span key={tag}>· {tag}</span>)}
                                </div>
                            ),
                        ]} />
                ),
                () => <MarkdownContent markdown={problem.statement ?? ""} />,
                ...(samples.length > 0 ? [
                    () => (
                        <StackV gap={4} principle="card-caption"
                            explain="Holds caption text under card media so the caption stays attached to the image above it."
                            items={[
                                () => <hr className="border-default" />,
                                () => <p className="font-semibold">{t("codingPractice.samples")}</p>,
                                ...samples.map((testcase, index) => () => (
                                    <IOExampleCard
                                        key={testcase.id}
                                        rows={[
                                            { key: "in", label: `${t("codingPractice.example")} ${index + 1} · ${t("codingPractice.input")}`, value: testcase.input },
                                            { key: "out", label: t("codingPractice.output"), value: testcase.expectedOutput },
                                        ]}
                                    />
                                )),
                            ]} />
                    ),
                ] : []),
                ...(hint ? [
                    () => (
                        <StackV gap={4} principle="card-caption"
                            explain="Holds caption text under card media so the caption stays attached to the image above it."
                            items={[
                                () => <hr className="border-default" />,
                                () => (
                                    <StackH gap={3} principle="flex-action" justify="between"
                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                        items={[
                                            () => <p className="font-semibold">{t("codingPractice.hintTitle")}</p>,
                                            () => (
                                                <Button size="sm" variant="secondary" onPress={() => setShowHint((prev) => !prev)}>
                                                    {showHint ? t("codingPractice.hideHint") : t("codingPractice.showHint")}
                                                </Button>
                                            ),
                                        ]} />
                                ),
                                ...(showHint ? [() => <MarkdownContent markdown={hint} />] : []),
                            ]} />
                    ),
                ] : []),
            ]} />
    )

    /** LEFT: reveal-gated reference solution, one tab per language. */
    const solutionPanel = (
        <StackV gap={4} principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            items={[
                () => (
                    <StackH gap={3} principle="flex-action" justify="between"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        items={[
                            () => <p className="font-semibold">{t("codingPractice.solutionTitle")}</p>,
                            () => (
                                <Button size="sm" variant="secondary" onPress={onToggleSolution}>
                                    {showSolution ? t("codingPractice.hideSolution") : t("codingPractice.showSolution")}
                                </Button>
                            ),
                        ]} />
                ),
                () => showSolution && solutionLanguages.length > 0 ? (
                    <StackV gap={4} principle="card-caption"
                        explain="Holds caption text under card media so the caption stays attached to the image above it."
                        items={[
                            () => (
                                <Cluster gap={3} principle="flex-action" explain="Groups action controls on one horizontal peer row so they share a single hit baseline." items={solutionLanguages.map((option) => () => (
                                    <Button
                                        key={option}
                                        size="sm"
                                        variant={solutionLanguage === option ? "primary" : "secondary"}
                                        onPress={() => setSolutionLanguage(option)}
                                    >
                                        {t(`codingPractice.language.${option}`)}
                                    </Button>
                                ))} />
                            ),
                            () => (
                                <MarkdownContent
                                    markdown={`\`\`\`${MONACO_LANGUAGE[solutionLanguage]}\n${
                                        solutionByLanguage.get(solutionLanguage) ?? ""
                                    }\n\`\`\``}
                                />
                            ),
                        ]} />
                ) : (
                    <Typography type="body-sm" color="muted">
                        {t("codingPractice.solutionLocked")}
                    </Typography>
                ),
            ]} />
    )

    /** LEFT: the learner's prior submissions for this problem. */
    const submissionsPanel = submissionsData && submissionsData.submissions.length > 0 ? (
        <SurfaceListCard>
            {submissionsData.submissions.map((submission: CodingSubmission) => (
                <SurfaceListCardRow
                    key={submission.id}
                    title={new Date(submission.createdAt).toLocaleString()}
                    meta={() => (
                        <>
                            <Typography type="body-xs" color="muted">
                                {t(`codingPractice.language.${submission.language}`)}
                            </Typography>
                            <StatusChip tone={VERDICT_TONE[submission.verdict]}>
                                {t(`codingPractice.verdict.${submission.verdict}`)}
                            </StatusChip>
                        </>
                    )}
                />
            ))}
        </SurfaceListCard>
    ) : (
        <EmptyState title={t("codingPractice.historyEmpty")} />
    )

    /** CONSOLE: sample testcases (pre-run reference). */
    const testcaseTab = samples.length > 0 ? (
        <StackV gap={4} principle="card-caption" explain="Holds caption text under card media so the caption stays attached to the image above it." items={samples.map((testcase, index) => () => (
            <IOExampleCard
                key={testcase.id}
                rows={[
                    { key: "in", label: `${t("codingPractice.example")} ${index + 1} · ${t("codingPractice.input")}`, value: testcase.input },
                    { key: "out", label: t("codingPractice.output"), value: testcase.expectedOutput },
                ]}
            />
        ))} />
    ) : (
        <Typography type="body-sm" color="muted">{t("codingPractice.noSamples")}</Typography>
    )

    /** CONSOLE: live judging / verdict + per-case grid + stats. */
    const resultTab = judging && pendingJobStatus ? (
        <AIProcessingText
            jobCategory={JobCategory.JudgeCoding}
            jobStatus={pendingJobStatus}
            error={pendingJobError}
        />
    ) : latestSubmission ? (
        <StackV gap={5} principle="group-boundary"
            explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
            items={[
                () => (
                    <Cluster gap={4} principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        items={[
                            () => (
                                <StatusChip tone={VERDICT_TONE[latestSubmission.verdict]}>
                                    {t(`codingPractice.verdict.${latestSubmission.verdict}`)}
                                </StatusChip>
                            ),
                            () => (
                                <Typography type="body-sm" color="muted">
                                    {t("codingPractice.passed")}: {latestSubmission.passedCount}/{latestSubmission.totalCount}
                                </Typography>
                            ),
                        ]} />
                ),
                () => (
                    <StatGridCard
                        items={[
                            {
                                key: "passed",
                                content: () => (
                                    <div className="flex flex-col gap-0">
                                        <span className="text-lg font-bold">{latestSubmission.passedCount}/{latestSubmission.totalCount}</span>
                                        <span className="text-xs text-muted">{t("codingPractice.statPassed")}</span>
                                    </div>
                                ),
                            },
                            {
                                key: "runtime",
                                content: () => (
                                    <div className="flex flex-col gap-0">
                                        <span className="text-lg font-bold">{latestSubmission.runtimeMs ?? "—"}<span className="text-xs"> ms</span></span>
                                        <span className="text-xs text-muted">{t("codingPractice.statRuntime")}</span>
                                    </div>
                                ),
                            },
                            {
                                key: "memory",
                                content: () => (
                                    <div className="flex flex-col gap-0">
                                        <span className="text-lg font-bold">{latestSubmission.memoryKb ?? "—"}<span className="text-xs"> KB</span></span>
                                        <span className="text-xs text-muted">{t("codingPractice.statMemory")}</span>
                                    </div>
                                ),
                            },
                        ]}
                    />
                ),
                ...(resultCases.length > 0 ? [
                    () => (
                        <TestCaseResultGrid
                            cases={resultCases}
                            labels={{
                                input: t("codingPractice.input"),
                                expected: t("codingPractice.expected"),
                                got: t("codingPractice.got"),
                                hidden: t("codingPractice.hiddenCase"),
                            }}
                        />
                    ),
                ] : []),
                ...(latestSubmission.compileOutput ? [
                    () => (
                        <pre data-principle="cell-pad" className="whitespace-pre-wrap rounded-2xl bg-danger-soft p-3 text-xs text-danger-soft-foreground">
                            {latestSubmission.compileOutput}
                        </pre>
                    ),
                ] : []),
            ]} />
    ) : (
        <Typography type="body-sm" color="muted">{t("codingPractice.resultEmpty")}</Typography>
    )

    return (
        // full-bleed 2-pane IDE: left reading column | right editor + console
        <div className="grid h-[calc(100vh-4rem)] grid-cols-1 @app-lg:grid-cols-2">

            {/* ── LEFT: tabbed reading column ── */}
            <div className="flex min-h-0 flex-col overflow-hidden border-r border-default">
                <Box principle="page-pad" className="flex flex-col border-b border-default px-6 py-3"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    <StackV gap={4} principle="card-caption"
                        explain="Holds caption text under card media so the caption stays attached to the image above it."
                        items={[
                            () => <BackLink target={t("codingPractice.title")} onPress={onBack} />,
                            () => (
                                <ExtendedTabs
                                    selectedKey={leftTab}
                                    onSelectionChange={(key) => setLeftTab(key as LeftTab)}
                                >
                                    <Tabs.ListContainer>
                                        <Tabs.List aria-label={problem.title}>
                                            <Tabs.Tab id="description">
                                                {t("codingPractice.tabDescription")}
                                                <Tabs.Indicator />
                                            </Tabs.Tab>
                                            <Tabs.Tab id="solution">
                                                {t("codingPractice.tabSolution")}
                                                <Tabs.Indicator />
                                            </Tabs.Tab>
                                            <Tabs.Tab id="submissions">
                                                {t("codingPractice.tabSubmissions")}
                                                <Tabs.Indicator />
                                            </Tabs.Tab>
                                        </Tabs.List>
                                    </Tabs.ListContainer>
                                </ExtendedTabs>
                            ),
                        ]} />
                </Box>
                <Box principle="page-pad" className="min-h-0 flex-1 overflow-auto px-6 py-5"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    {leftTab === "description" && descriptionPanel}
                    {leftTab === "solution" && solutionPanel}
                    {leftTab === "submissions" && submissionsPanel}
                </Box>
            </div>

            {/* ── RIGHT: editor + console ── */}
            <div className="flex min-h-0 flex-col overflow-hidden">
                {/* language selector + reset */}
                <Box principle="pill-pad" className="flex flex-wrap items-center justify-between border-b border-default px-4 py-2"
                    explain="Pill/chip inset — not control-pad, because this pads a compact badge shape rather than a form control.">
                    <Cluster gap={3} principle="flex-action" explain="Groups action controls on one horizontal peer row so they share a single hit baseline." items={languages.map((option) => () => (
                        <Button
                            key={option}
                            size="sm"
                            variant={language === option ? "primary" : "secondary"}
                            onPress={() => setLanguage(option)}
                        >
                            {t(`codingPractice.language.${option}`)}
                        </Button>
                    ))} />
                    <Button size="sm" variant="tertiary" onPress={onResetCode}>
                        <ArrowCounterClockwiseIcon className="size-4" aria-hidden focusable="false" />
                        {t("codingPractice.resetCode")}
                    </Button>
                </Box>

                {/* Monaco editor */}
                <div className="min-h-0 flex-1">
                    <Editor
                        height="100%"
                        language={MONACO_LANGUAGE[language]}
                        theme={theme === "dark" ? "vs-dark" : "light"}
                        value={code}
                        onChange={(value) => {
                            setCode(value ?? "")
                            setTouchedLanguages((prev) => new Set(prev).add(language))
                        }}
                        onMount={(editor) => {
                            editor.getDomNode()?.querySelector("textarea")?.setAttribute("spellcheck", "false")
                            editor.onDidPaste((e) => {
                                const model = editor.getModel()
                                const pastedText = model ? model.getValueInRange(e.range) : ""
                                const size = pastedText.length
                                telemetryRef.current.pasteCount += 1
                                telemetryRef.current.pasteSizeMax = Math.max(
                                    telemetryRef.current.pasteSizeMax,
                                    size
                                )
                            })
                            editor.onKeyDown(() => {
                                telemetryRef.current.keystrokeCount += 1
                            })
                            editor.onDidBlurEditorText(() => {
                                telemetryRef.current.tabBlurCount += 1
                            })
                        }}
                        options={{
                            minimap: { enabled: false },
                            fontSize: 14,
                            scrollBeyondLastLine: false,
                            padding: { top: 12, bottom: 12 },
                            bracketPairColorization: { enabled: true },
                            cursorBlinking: "smooth",
                            smoothScrolling: true,
                        }}
                    />
                </div>

                {/* bottom console — Test case / Result + Run/Submit bar */}
                <CodeConsole
                    className="h-[42%]"
                    ariaLabel={t("codingPractice.consoleLabel")}
                    selectedTab={consoleTab}
                    onSelectTab={(key) => setConsoleTab(key as ConsoleTab)}
                    tabs={[
                        { key: "testcase", label: t("codingPractice.tabTestcase"), content: testcaseTab },
                        { key: "result", label: t("codingPractice.tabResult"), content: resultTab },
                    ]}
                    hint={t("codingPractice.runVsSubmit")}
                    actions={(
                        <>
                            {/* "Run on sample" needs a dedicated judge-sample endpoint on the BE —
                                doesn't exist yet, so it's left disabled (the console hint explains it) instead of silently dropping it. */}
                            <Button
                                size="sm"
                                variant="secondary"
                                isDisabled
                            >
                                <PlayIcon className="size-4" aria-hidden focusable="false" />
                                {t("codingPractice.run")}
                            </Button>
                            <Button
                                size="sm"
                                variant="primary"
                                isPending={submitting || judging}
                                isDisabled={code.trim().length === 0}
                                onPress={onSubmit}
                            >
                                {judging ? t("codingPractice.judging") : t("codingPractice.submit")}
                            </Button>
                        </>
                    )}
                />
            </div>
        </div>
    )
}

"use client"

import React, {
    useCallback,
    useState,
} from "react"
import type { ReactNode } from "react"
import {
    Button,
    Card,
    Chip,
    Input,
    Label,
    Skeleton,
    TextField,
    Typography,
} from "@heroui/react"
import { toast } from "@/modules/toast/toast"
import { useTranslations } from "next-intl"
import {
    CheckCircleIcon,
    CopyIcon,
    GiftIcon,
    LightningIcon,
    SnowflakeIcon,
    TShirtIcon,
    TicketIcon,
} from "@phosphor-icons/react"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { Callout } from "@/components/composites/feedback/Callout"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { useMutateRedeemRewardSwr } from "@/hooks/swr/api/graphql/mutations/useMutateRedeemRewardSwr"
import { useQueryMyRewardWalletSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyRewardWalletSwr"
import { useQueryMyVouchersSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyVouchersSwr"
import { useQueryRewardsSwr } from "@/hooks/swr/api/graphql/queries/useQueryRewardsSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import type { QueryRewardData } from "@/modules/api/graphql/queries/types/rewards"
import type { RedeemRewardAiCreditGrant } from "@/modules/api/graphql/mutations/types/redeem-reward"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { Box } from "@/components/frames/Box"
import { Grid } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"

/** Icon per catalog item, keyed by its stable reward key (falls back to a generic gift). */
const REWARD_ICON: Record<string, ReactNode> = {
    streakFreeze: <SnowflakeIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
    aiCreditBoost: <LightningIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
    voucher10: <TicketIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
    tshirt: <TShirtIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
}

/**
 * Coin-shop catalog grouped into user-facing SECTIONS by reward `kind` (instructor's
 * call, 2026-07-17, "split into more categories"). `aiCredit` + `digital` read as one
 * "speed up learning" bucket; `voucher` and `physical` each stand alone. Order = display
 * order. A reward whose `kind` matches no section is not shown in the grouped view —
 * every current kind is covered here; adding a new kind means adding a section.
 */
const REWARD_SECTIONS: ReadonlyArray<{ key: string, icon: ReactNode, kinds: ReadonlyArray<string> }> = [
    { key: "learn", icon: <LightningIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />, kinds: ["aiCredit", "digital"] },
    { key: "voucher", icon: <TicketIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />, kinds: ["voucher"] },
    { key: "physical", icon: <GiftIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />, kinds: ["physical"] },
]

/** One redeem effect's takeaway shown right after redeeming (voucher code / AI-credit bump). */
type JustRedeemed =
    | { kind: "voucher", code: string }
    | { kind: "aiCredit", grant: RedeemRewardAiCreditGrant }

/** Shipping form fields (physical rewards only). */
interface ShippingForm {
    recipientName: string
    phone: string
    address: string
}

const EMPTY_SHIPPING: ShippingForm = {
    recipientName: "",
    phone: "",
    address: "",
}

/** Props for {@link RewardCatalog}. */
export type RewardCatalogProps = WithClassNames<undefined>

/**
 * The Coin shop's "Store" tab: the redeemable catalog grid. Self-fetches the
 * catalog + the viewer's balance (the wallet SWR key is shared with the header
 * and the "My Wallet" tab, so a redeem here refreshes both instantly). Physical
 * rewards expand an inline shipping form before redeeming; a `voucher`/`aiCredit`
 * redemption surfaces its takeaway (code to copy / bonus credit granted) in a
 * dismissible callout above the grid.
 *
 * @param props - optional className for the root element.
 */
export const RewardCatalog = ({ className }: RewardCatalogProps) => {
    const t = useTranslations()
    const rewardsSwr = useQueryRewardsSwr()
    const walletSwr = useQueryMyRewardWalletSwr()
    const vouchersSwr = useQueryMyVouchersSwr()
    const { trigger: triggerRedeem } = useMutateRedeemRewardSwr()
    const runGraphQL = useGraphQLWithToast()

    /** The reward key currently being redeemed (single in-flight redeem). */
    const [redeeming, setRedeeming] = useState<string | null>(null)
    /** The physical reward whose shipping form is open (null = none). */
    const [shippingFor, setShippingFor] = useState<string | null>(null)
    const [ship, setShip] = useState<ShippingForm>(EMPTY_SHIPPING)
    /** The takeaway of the most recent voucher/aiCredit redemption, if any. */
    const [justRedeemed, setJustRedeemed] = useState<JustRedeemed | null>(null)
    /** A non-physical reward awaiting spend confirmation (Coin is real, redeem is irreversible). */
    const [confirming, setConfirming] = useState<QueryRewardData | null>(null)

    const balance = walletSwr.data?.balance ?? 0

    const onRedeem = useCallback(
        async (reward: QueryRewardData, shipping?: ShippingForm) => {
            setRedeeming(reward.key)
            try {
                let redeemed: { voucherCode?: string | null, aiCreditGranted?: RedeemRewardAiCreditGrant | null } | undefined
                const ok = await runGraphQL(async () => {
                    const result = await triggerRedeem({
                        rewardKey: reward.key,
                        ...shipping,
                    })
                    const wrapped = result.data!.redeemReward
                    redeemed = wrapped.data
                    return wrapped
                })
                if (ok) {
                    await walletSwr.mutate()
                    if (reward.kind === "voucher" && redeemed?.voucherCode) {
                        setJustRedeemed({ kind: "voucher", code: redeemed.voucherCode })
                        await vouchersSwr.mutate()
                    } else if (reward.kind === "aiCredit" && redeemed?.aiCreditGranted) {
                        setJustRedeemed({ kind: "aiCredit", grant: redeemed.aiCreditGranted })
                    }
                    // close + reset the shipping form on success
                    setShippingFor(null)
                    setShip(EMPTY_SHIPPING)
                }
            } finally {
                setRedeeming(null)
            }
        },
        [
            triggerRedeem,
            walletSwr,
            vouchersSwr,
            runGraphQL,
        ],
    )

    const onCopyCode = useCallback(
        async (code: string) => {
            try {
                await navigator.clipboard.writeText(code)
                toast.success(t("rewards.myVouchers.copied"))
            } catch {
                // clipboard blocked (permissions/http) → no-op, code is still selectable text
            }
        },
        [t],
    )

    return (
        <Box className={className}>
            <StackV gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (justRedeemed ? (
                        <Callout
                            status="accent"
                            icon={CheckCircleIcon}
                            title={
                                justRedeemed.kind === "voucher"
                                    ? t("rewards.justRedeemed.voucherTitle")
                                    : t("rewards.justRedeemed.aiCreditTitle")
                            }
                            description={
                                justRedeemed.kind === "voucher"
                                    ? undefined
                                    : t("rewards.justRedeemed.aiCreditDescription", {
                                        amount5h: justRedeemed.grant.amount5h,
                                        amountWeek: justRedeemed.grant.amountWeek,
                                    })
                            }
                            body={justRedeemed.kind === "voucher" ? () => (
                                <StackH gap={3} principle="flex-action"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    align="center" items={[
                                        () => <span className="font-mono font-medium text-foreground">{justRedeemed.code}</span>,
                                        () => (
                                            <Button
                                                variant="tertiary"
                                                size="sm"
                                                onPress={() => void onCopyCode(justRedeemed.code)}
                                            >
                                                <CopyIcon aria-hidden focusable="false" className="size-4" />
                                                {t("rewards.myVouchers.copy")}
                                            </Button>
                                        ),
                                    ]} />
                            ) : undefined}
                            onClose={() => setJustRedeemed(null)}
                            closeAriaLabel={t("rewards.justRedeemed.dismiss")}
                        />
                    ) : null),

                    () => (
                        <AsyncContent
                            isLoading={!rewardsSwr.data}
                            skeleton={(
                                <Grid
                                    columns={{ base: 1, sm: 2 }}
                                    principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={Array.from({ length: 4 }).map((_, index) => ({
                                        key: String(index),
                                        content: () => (
                                            <Box principle="card-padding" className="rounded-3xl bg-surface p-4 shadow-surface"
                                                explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                                <StackV gap={4} principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => (
                                                            <StackH gap={4} principle="content-row"
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                align="center" items={[
                                                                    () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                                                    () => <Skeleton className="h-4 w-1/2 rounded-lg" />,
                                                                ]} />
                                                        ),
                                                        () => <Skeleton className="h-4 w-full rounded-lg" />,
                                                        () => <Skeleton className="h-9 w-24 self-end rounded-lg" />,
                                                    ]} />
                                            </Box>
                                        ),
                                    }))}
                                />
                            )}
                            isEmpty={(rewardsSwr.data ?? []).length === 0}
                            emptyContent={{
                                icon: <GiftIcon aria-hidden focusable="false" className="size-8 text-muted" />,
                                title: t("rewards.catalogEmptyTitle"),
                                description: t("rewards.catalogEmptyDescription"),
                            }}
                            error={rewardsSwr.error}
                            errorContent={{
                                title: t("rewards.catalogError"),
                                onRetry: () => void rewardsSwr.mutate(),
                            }}
                        >
                            <StackV gap={6} principle="block-boundary" explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups." items={REWARD_SECTIONS.map((section) => () => {
                                const sectionItems = (rewardsSwr.data ?? []).filter((reward) => section.kinds.includes(reward.kind))
                                if (sectionItems.length === 0) {
                                    return null
                                }
                                return (
                                    <LabeledCard
                                        key={section.key}
                                        // `label` is plain text now (never a built element) — `LabeledCard`
                                        // has no leading-icon slot the way `SectionCard` does, so the
                                        // per-section icon has nowhere left to attach (flagged for a
                                        // follow-up: a real icon slot on `LabeledCard`, or switch this
                                        // section header to `SectionCard`).
                                        label={t(`rewards.section.${section.key}`)}
                                    >
                                        <Grid
                                            columns={{ base: 1, sm: 2 }}
                                            principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            items={sectionItems.map((reward) => ({
                                                key: reward.key,
                                                content: () => {
                                                    const affordable = balance >= reward.cost
                                                    const isPhysical = reward.kind === "physical"
                                                    const formOpen = shippingFor === reward.key
                                                    const shipReady = Boolean(
                                                        ship.recipientName.trim()
                                && ship.phone.trim()
                                && ship.address.trim(),
                                                    )
                                                    return (
                                                        <Card>
                                                            <StackV gap={4} principle="content-row"
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                items={[
                                                                    () => (
                                                                        <StackH gap={4} principle="content-row"
                                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                            align="start" items={[
                                                                                () => (
                                                                                    <IconTile
                                                                                        size="sm"
                                                                                        tone="accent"
                                                                                        icon={REWARD_ICON[reward.key] ?? (
                                                                                            <GiftIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />
                                                                                        )}
                                                                                    />
                                                                                ),
                                                                                () => (
                                                                                    <StackV gap={1} principle="name-handle"
                                                                                        explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                                                        classNames={["min-w-0", "flex-1"]} items={[
                                                                                            () => (
                                                                                                <span className="truncate text-sm font-semibold text-foreground">
                                                                                                    {reward.title}
                                                                                                </span>
                                                                                            ),
                                                                                            () => (
                                                                                                <span className="text-xs text-muted">
                                                                                                    {reward.description}
                                                                                                </span>
                                                                                            ),
                                                                                        ]} />
                                                                                ),
                                                                            ]} />
                                                                    ),
                                                                    () => (
                                                                        <StackH gap={4} principle="content-row" justify="between" align="center"
                                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                            items={[
                                                                                () => (
                                                                                    <Chip color="accent" variant="soft" size="sm">
                                                                                        <Chip.Label>
                                                                                            {t("rewards.cost", { count: reward.cost })}
                                                                                        </Chip.Label>
                                                                                    </Chip>
                                                                                ),
                                                                                () => (!formOpen ? (
                                                                                    <Button
                                                                                        variant="primary"
                                                                                        size="sm"
                                                                                        isDisabled={!affordable || redeeming !== null}
                                                                                        isPending={redeeming === reward.key}
                                                                                        onPress={() => {
                                                                                            if (isPhysical) {
                                                                                                setShippingFor(reward.key)
                                                                                            } else {
                                                                                                // Coin is real + redeem is irreversible — confirm
                                                                                                // before spending (mirrors the shipping form's own
                                                                                                // "Confirm redeem" step for physical rewards).
                                                                                                setConfirming(reward)
                                                                                            }
                                                                                        }}
                                                                                    >
                                                                                        {affordable
                                                                                            ? t("rewards.redeem")
                                                                                            : t("rewards.cannotAfford")}
                                                                                    </Button>
                                                                                ) : null),
                                                                            ]} />
                                                                    ),
                                                                    () => (formOpen ? (
                                                                        <StackV gap={3} principle="sibling-stack"
                                                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                                            items={[
                                                                                () => (
                                                                                    <TextField variant="secondary">
                                                                                        <Label htmlFor={`reward-ship-name-${reward.key}`}>
                                                                                            {t("rewards.shipName")}
                                                                                        </Label>
                                                                                        <Input
                                                                                            id={`reward-ship-name-${reward.key}`}
                                                                                            value={ship.recipientName}
                                                                                            onChange={(event) => setShip((prev) => ({
                                                                                                ...prev,
                                                                                                recipientName: event.target.value,
                                                                                            }))}
                                                                                        />
                                                                                    </TextField>
                                                                                ),
                                                                                () => (
                                                                                    <TextField variant="secondary">
                                                                                        <Label htmlFor={`reward-ship-phone-${reward.key}`}>
                                                                                            {t("rewards.shipPhone")}
                                                                                        </Label>
                                                                                        <Input
                                                                                            id={`reward-ship-phone-${reward.key}`}
                                                                                            type="tel"
                                                                                            value={ship.phone}
                                                                                            onChange={(event) => setShip((prev) => ({
                                                                                                ...prev,
                                                                                                phone: event.target.value,
                                                                                            }))}
                                                                                        />
                                                                                    </TextField>
                                                                                ),
                                                                                () => (
                                                                                    <TextField variant="secondary">
                                                                                        <Label htmlFor={`reward-ship-address-${reward.key}`}>
                                                                                            {t("rewards.shipAddress")}
                                                                                        </Label>
                                                                                        <Input
                                                                                            id={`reward-ship-address-${reward.key}`}
                                                                                            value={ship.address}
                                                                                            onChange={(event) => setShip((prev) => ({
                                                                                                ...prev,
                                                                                                address: event.target.value,
                                                                                            }))}
                                                                                        />
                                                                                    </TextField>
                                                                                ),
                                                                                () => (
                                                                                    <StackH gap={3} principle="flex-action"
                                                                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                                                        align="center" items={[
                                                                                            () => (
                                                                                                <Button
                                                                                                    variant="primary"
                                                                                                    size="sm"
                                                                                                    isDisabled={!shipReady || redeeming !== null}
                                                                                                    isPending={redeeming === reward.key}
                                                                                                    onPress={() => void onRedeem(reward, ship)}
                                                                                                >
                                                                                                    {t("rewards.confirmRedeem")}
                                                                                                </Button>
                                                                                            ),
                                                                                            () => (
                                                                                                <Button
                                                                                                    variant="tertiary"
                                                                                                    size="sm"
                                                                                                    onPress={() => setShippingFor(null)}
                                                                                                >
                                                                                                    {t("rewards.cancel")}
                                                                                                </Button>
                                                                                            ),
                                                                                        ]} />
                                                                                ),
                                                                            ]} />
                                                                    ) : null),
                                                                ]} />
                                                        </Card>
                                                    )
                                                },
                                            }))}
                                        />
                                    </LabeledCard>
                                )
                            })} />
                        </AsyncContent>
                    ),

                    // spend confirmation for non-physical rewards — Coin is real + redeem is
                    // irreversible, so a single accidental tap must never fire it (mirrors the
                    // shipping form's own "Confirm redeem" step for physical rewards).
                    () => (
                        <ModalShell
                            isOpen={confirming !== null}
                            onOpenChange={(open) => {
                                if (!open) {
                                    setConfirming(null)
                                }
                            }}
                            title={t("rewards.confirmRedeem")}
                            size="sm"
                            body={() => (
                                <Typography type="body-sm" color="muted">
                                    {confirming
                                        ? t("rewards.confirmRedeemBody", { cost: confirming.cost, title: confirming.title })
                                        : null}
                                </Typography>
                            )}
                            footer={() => (
                                <>
                                    <Button variant="tertiary" onPress={() => setConfirming(null)}>
                                        {t("rewards.cancel")}
                                    </Button>
                                    <Button
                                        variant="primary"
                                        isPending={redeeming !== null}
                                        onPress={() => {
                                            const reward = confirming
                                            setConfirming(null)
                                            if (reward) {
                                                void onRedeem(reward)
                                            }
                                        }}
                                    >
                                        {t("rewards.confirmRedeem")}
                                    </Button>
                                </>
                            )}
                        />
                    ),
                ]} />
        </Box>
    )
}
